-- Passage rg3-connections-p03
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('00ec2600-e2e5-5534-b30a-bd1c559aee75', 'rg3-connections-p03', (select id from public.skills where slug = 'read-g3-connections'), null,
        '3-5', $q$Where Rain Comes From$q$, $q$The water you drink today may once have been part of an ocean, a cloud or even a puddle. Water moves around Earth again and again. This path is called the water cycle.

The cycle often starts with the sun. The sun warms water in oceans, lakes and rivers. As the water warms, some of it turns into a gas called water vapor. This change is called evaporation. You cannot see water vapor, but it rises into the air.

High in the sky, the air is much colder. The cold air cools the water vapor. As it cools, the vapor turns back into tiny drops of water. This change is called condensation. Millions of these tiny drops crowd together and form a cloud.

Inside the cloud, the tiny drops bump into each other and join. They become bigger and heavier. Soon the drops are too heavy to float. They fall to the ground as rain. If the air is very cold, the water may fall as snow instead.

The rain flows into rivers, lakes and oceans. Some of it soaks into the ground. Then the sun warms the water again, and the cycle keeps going.$q$, 'draft')
