-- Passage rg3-literary-structure-pov-p01
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('94eb9081-a3a5-53dd-bbd3-2e5abfced9d6', 'rg3-literary-structure-pov-p01', (select id from public.skills where slug = 'read-g3-literary-structure-pov'), null,
        '3-5', $q$My Bean Seed$q$, $q$In April I pressed a bean seed down,
Into a cup of soft, dark ground.
I gave it water, just a sip.
And set it down with careful grip.

For three long days the dirt sat still.
I checked it on the windowsill.
I said, "My seed is lost for good.
It will not grow the way it should."

Then on day four, a tiny hook
Came poking up. I bent to look.
Two leaves unfolded, green and new.
They seemed to wave, "We grew! We grew!"

Now when I wait for things that take
A long, long time, I do not shake.
I think about my little bean.
Good things grow where they cannot be seen.$q$, 'draft')
