-- Passage rg3-theme-summary-p06
insert into public.passages (id, code, skill_id, sat_alignment, grade_band, title, body, status)
values ('45e8d202-b39c-500e-a702-bdbe2cec142c', 'rg3-theme-summary-p06', (select id from public.skills where slug = 'read-g3-theme-summary'), null,
        '3-5', $q$Rainy Day Plans$q$, $q$We planned a picnic at the park,
With sandwiches and lemonade.
But gray clouds rolled in, thick and dark,
And rain came down. The picnic? Delayed.

I pressed my nose against the glass.
I watched the puddles grow and spread.
No swings, no slide, no soft green grass.
"This day is ruined," I said.

My dad just laughed and found a sheet.
We built a tent across two chairs.
We spread our blanket at our feet
And ate our lunch beneath the stairs.

We played a game of flashlight tag.
We told a story, silly and long.
The rain kept drumming. I didn't mind.
It sounded like a picnic song.

Now when the clouds roll in, I know
A day can change and still be good.
A picnic plan can always grow
Into something new, if you think it could.$q$, 'draft')
