  ('7904d484-3745-58ca-88c7-a465f5de1bf1', null, (select id from public.skills where slug = 'read-g4-authors-purpose'), null, 'hard',
   $q$Why does the article tell how old the tracks are and what made them, while Marco's journal does not?$q$, $q$[{"text":"The article used what scientists learned after their visit, but Marco wrote on the same day the prints were found.","is_correct":true},{"text":"The article writer was walking in the riverbed with Marco and Lucia when the prints were found.","is_correct":false,"misconception_token":"misreads-source"},{"text":"Marco knew how old the tracks were, but forgot to write it down before hiking home.","is_correct":false,"misconception_token":"unsupported-inference"},{"text":"Marco was not interested in dinosaurs and chose to leave out the facts Marco knew about them.","is_correct":false,"misconception_token":"unsupported-inference"}]$q$::jsonb, $q$The article used what scientists learned after their visit, but Marco wrote on the same day the prints were found.$q$, $q$Scientists visited "later" and then shared their ideas about age and the kind of dinosaur, so a writer after that could include them. Marco wrote on June 21, before any scientist had studied the tracks.$q$, 'draft', '100dc7b8-ce9d-53d3-87bc-98a28773aa14')
